28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "birth_date")
59	    private LocalDate birthDate;
60	
61	    @Column(name = "customer_code")
62	    private String customerCode;
63	
64	    @Column(name = "household_id")
65	    private String householdId;
66	
67	    @Column(name = "namesake_count")
68	    private Integer namesakeCount;
69	
70	    @Column(name = "membership_number")
71	    private String membershipNumber;
72	
73	    @Column(name = "bulk_signup_warning")
74	    private Boolean bulkSignupWarning;
75	
76	    @Column(name = "household_size")
77	    private Integer householdSize;
78	
79	    @Column(name = "postcode")
80	    private String postcode;
81	
82	    @Column(name = "possible_duplicate_of")
83	    private Integer possibleDuplicateOf;
84	
85	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
86	    private Set<Pet> pets;
87	
88	    public String getAddress() {
89	        return this.address;
90	    }
91	
92	    public void setAddress(String address) {
93	        this.address = address;
94	    }
95	
96	    public String getCity() {
97	        return this.city;
98	    }
99	
100	    public void setCity(String city) {
101	        this.city = city;
102	    }
103	
104	    public String getTelephone() {
105	        return this.telephone;
106	    }
107	
108	    public void setTelephone(String telephone) {
109	        this.telephone = telephone;
110	    }
111	
112	    /**
113	     * Return this owner's stored E.164 {@link #getTelephone() telephone} formatted for human display
114	     * as the calling code, a space, then the national digits grouped in threes, e.g.
115	     * {@code "+61 412 345 678"}. See {@link TelephoneFormatter}.
116	     */
117	    @Transient
118	    public String getTelephoneDisplay() {
119	        return TelephoneFormatter.toDisplay(this.telephone);
120	    }
121	
122	    public String getEmail() {
123	        return this.email;
124	    }
125	
126	    public void setEmail(String email) {
127	        this.email = email;
128	    }
129	
130	    public LocalDate getRegistrationDate() {
131	        return this.registrationDate;
132	    }
133	
134	    public void setRegistrationDate(LocalDate registrationDate) {
135	        this.registrationDate = registrationDate;
136	    }
137	
138	    public LocalDate getBirthDate() {
139	        return this.birthDate;
140	    }
141	
142	    public void setBirthDate(LocalDate birthDate) {
143	        this.birthDate = birthDate;
144	    }
145	
146	    public String getCustomerCode() {
147	        return this.customerCode;
148	    }
149	
150	    public void setCustomerCode(String customerCode) {
151	        this.customerCode = customerCode;
152	    }
153	
154	    public String getHouseholdId() {
155	        return this.householdId;
156	    }
157	
158	    public void setHouseholdId(String householdId) {
159	        this.householdId = householdId;
160	    }
161	
162	    public Integer getNamesakeCount() {
163	        return this.namesakeCount;
164	    }
165	
166	    public void setNamesakeCount(Integer namesakeCount) {
167	        this.namesakeCount = namesakeCount;
168	    }
169	
170	    public String getMembershipNumber() {
171	        return this.membershipNumber;
172	    }
173	
174	    public void setMembershipNumber(String membershipNumber) {
175	        this.membershipNumber = membershipNumber;
176	    }
177	
178	    /**
179	     * Whether this owner was created after more than 80 owners had already been registered on the
180	     * same day, flagging an unusually high-volume ("bulk") signup. Captured once at creation.
181	     */
182	    public Boolean getBulkSignupWarning() {
183	        return this.bulkSignupWarning;
184	    }
185	
186	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
187	        this.bulkSignupWarning = bulkSignupWarning;
188	    }
189	
190	    /**
191	     * The number of owners in this owner's household (owners sharing the same {@code householdId},
192	     * counting this owner) captured once at creation.
193	     */
194	    public Integer getHouseholdSize() {
195	        return this.householdSize;
196	    }
197	
198	    public void setHouseholdSize(Integer householdSize) {
199	        this.householdSize = householdSize;
200	    }
201	
202	    /**
203	     * This owner's 4-digit postcode, or {@code null} when none was supplied. When present it is
204	     * validated against the owner's city region at creation (see {@code PostcodeValidator}).
205	     */
206	    public String getPostcode() {
207	        return this.postcode;
208	    }
209	
210	    public void setPostcode(String postcode) {
211	        this.postcode = postcode;
212	    }
213	
214	    /**
215	     * The id of an existing owner this owner was flagged as a possible (soft) duplicate of at
216	     * creation, or {@code null} when none. Because owners sharing a last name and postcode now form
217	     * the same household — rejected as a household duplicate unless declared via {@code sharesHousehold},
218	     * and a declared member is not a suspected duplicate — this is not populated at creation.
219	     * Captured once at creation.
220	     */
221	    public Integer getPossibleDuplicateOf() {
222	        return this.possibleDuplicateOf;
223	    }
224	
225	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
226	        this.possibleDuplicateOf = possibleDuplicateOf;
227	    }
228	
229	    /**
230	     * Whether this owner was flagged as a possible (soft) duplicate of an existing owner at creation,
231	     * i.e. whether {@link #getPossibleDuplicateOf()} is set.
232	     */
233	    @Transient
234	    public Boolean getPossibleDuplicate() {
235	        return this.possibleDuplicateOf != null;
236	    }
237	
238	    /**
239	     * Return this owner's name formatted for display as {@code "LastName, FirstName"}.
240	     */
241	    @Transient
242	    public String getDisplayName() {
243	        return this.getLastName() + ", " + this.getFirstName();
244	    }
245	
246	    /**
247	     * Return this owner's initials as the upper-cased first letters of the first and last
248	     * name, dot-separated with a trailing dot, e.g. {@code "J.S."}.
249	     */
250	    @Transient
251	    public String getInitials() {
252	        return initial(this.getFirstName()) + initial(this.getLastName());
253	    }
254	
255	    private static String initial(String name) {
256	        return Character.toUpperCase(name.charAt(0)) + ".";
257	    }
258	
259	    /** Points awarded when an email address is present. */
260	    private static final int EMAIL_POINTS = 2;
261	
262	    /** Points awarded when the owner has no namesakes ({@code namesakeCount} is 0). */
263	    private static final int NO_NAMESAKE_POINTS = 1;
264	
265	    /** Points awarded for belonging to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more. */
266	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
267	
268	    /** The household size at or above which {@link #LARGE_HOUSEHOLD_POINTS} are awarded. */
269	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
