260	    /**
261	     * Count the members of the given (not yet persisted) owner's household: the already stored
262	     * owners sharing its {@code householdId} plus the owner itself. An owner with no household
263	     * ({@code householdId} is null) is a household of one. Used to capture an owner's household
264	     * size at creation time.
265	     */
266	    private int countHouseholdMembers(Owner owner) {
267	        String householdId = owner.getHouseholdId();
268	        if (householdId == null) {
269	            return 1;
270	        }
271	        long existing = ownerRepository.findAll().stream()
272	            .filter(existingOwner -> householdId.equals(existingOwner.getHouseholdId()))
273	            .count();
274	        return (int) (existing + 1);
275	    }
