18	
19	import java.util.regex.Pattern;
20	
21	import org.springframework.samples.petclinic.model.LocalityResolver;
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Validates an owner's optional {@code postcode} against the region of their city.
26	 *
27	 * <p>A postcode is optional: when absent nothing is checked. When present it must be exactly four
28	 * digits and, for a city whose region is known (via {@link LocalityResolver}), must fall within
29	 * that region's inclusive range. A city with no known region accepts any four-digit postcode.
30	 */
31	@Component
32	public class PostcodeValidator {
33	
34	    private static final Pattern FOUR_DIGITS = Pattern.compile("\\d{4}");
35	
36	    /**
37	     * @param postcode the submitted postcode, or {@code null}/absent
38	     * @param city     the owner's city, used to resolve the applicable region
39	     * @throws InvalidPostcodeException if the postcode is present but not four digits, or is out of
40	     *                                  range for the city's region
41	     */
42	    public void validate(String postcode, String city) {
43	        if (postcode == null) {
44	            return;
45	        }
46	        if (!FOUR_DIGITS.matcher(postcode).matches()) {
47	            throw new InvalidPostcodeException(postcode);
48	        }
49	        int[] range = LocalityResolver.rangeForRegion(LocalityResolver.regionForCity(city));
50	        if (range == null) {
51	            return;
52	        }
53	        int value = Integer.parseInt(postcode);
54	        if (value < range[0] || value > range[1]) {
55	            throw new InvalidPostcodeException(postcode);
56	        }
57	    }
58	}
