21	
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Rejects owner emails whose domain belongs to a known disposable-email provider.
26	 *
27	 * <p>Its single responsibility is to hold the blocklist and decide whether a given
28	 * address is disposable; email syntax and normalization are handled separately by
29	 * {@link EmailNormalizer}.
30	 */
31	@Component
32	public class DisposableEmailDomainValidator {
33	
34	    /** Domains that provide throwaway, disposable mailboxes. */
35	    private static final Set<String> BLOCKED_DOMAINS =
36	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
37	
38	    /**
39	     * Validates that the address does not use a disposable-email domain.
40	     *
41	     * @param email a normalized email address, or {@code null} when none was supplied
42	     * @throws DisposableEmailDomainException if the domain is on the blocklist
43	     */
44	    public void validate(String email) {
45	        if (email == null) {
46	            return;
47	        }
48	        int at = email.lastIndexOf('@');
49	        if (at < 0) {
50	            return;
51	        }
52	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
53	        if (BLOCKED_DOMAINS.contains(domain)) {
54	            throw new DisposableEmailDomainException(domain);
55	        }
56	    }
57	}
